const inp = $input.first();
const b = (inp.json && inp.json.body) || {};
const ts = Math.floor(Date.now()/1000);
const phone = b.phone ? String(b.phone).replace(/[^\d]/g,'') : null;
const to = b.to ? String(b.to).replace(/[^\d]/g,'') : (phone || null);
const ch = ['whatsapp','instagram','facebook'].includes(String(b.channel||'').toLowerCase()) ? String(b.channel).toLowerCase() : 'whatsapp';
let mediaMime = b.mediaMime || null;
let mediaName = b.filename || null;
let mediaB64 = b.mediaBase64 || null;
if (mediaB64) mediaB64 = String(mediaB64).replace(/^data:[^;]+;base64,/, '').replace(/\s/g, '');
if (!mediaB64 && inp.binary) { try { const key = Object.keys(inp.binary)[0]; if (key) { const bd = inp.binary[key] || {}; const buf = await this.helpers.getBinaryDataBuffer(0, key); mediaB64 = buf.toString('base64'); if (!mediaMime) mediaMime = bd.mimeType || null; if (!mediaName) mediaName = bd.fileName || null; } } catch(e){} }
const caption = b.text || b.caption || '';
const VALID = ['image','audio','video','document'];
let type = String(b.type||'').toLowerCase();
if (!VALID.includes(type)) { const m = (mediaMime||'').toLowerCase(); if (m.startsWith('image/')) type='image'; else if (m.startsWith('audio/')) type='audio'; else if (m.startsWith('video/')) type='video'; else type='document'; }
const LBL = { image:'\uD83D\uDCF7 Imagen', audio:'\uD83C\uDFB5 Audio', video:'\uD83C\uDFAC Video', document:('\uD83D\uDCC4 '+(mediaName||'Documento')) };
const preview = caption || LBL[type];
return [{ json: { contactId: b.contactId!=null ? String(b.contactId) : null, name: b.name||null, text: caption, wamid: null, ts, type, direction: 'out', status: 'sent', phone, channel: ch, mediaUrl: null, mediaMime, mediaName, preview, mediaB64, to, caption, filename: mediaName || 'documento' } }];

const pg = ($input.first() && $input.first().json) || {};
const norm = $('Normalize').first().json;
const id = pg.id != null ? String(pg.id) : null;
const mediaUrl = id ? ('https://n8n.lmconsultingai.com/webhook/wa-media?id=' + id) : null;
const t = norm.type;
const media = { link: mediaUrl };
if (t === 'document') media.filename = norm.filename;
if (norm.caption && t !== 'audio') media.caption = norm.caption;
const waBody = { messaging_product: 'whatsapp', to: norm.to, type: t };
waBody[t] = media;
return [{ json: { id, conversationId: pg.conversation_id != null ? String(pg.conversation_id) : null, waBody, hasUrl: !!mediaUrl } }];

const r = ($input.first() && $input.first().json) || {};
const bu = $('Build URL').first().json;
const wamid = (r.messages && r.messages[0]) ? r.messages[0].id : null;
return [{ json: { ok: true, id: bu.id, conversationId: bu.conversationId, wamid, sent: !!wamid } }];
